from pypdf import PdfReader
from pathlib import Path
import re
r=PdfReader('manuscript.pdf')
def decode(m):
    i=int(m.group(1),16)
    return '-' if i==0xed else chr(i+29)
for i in range(10,16):
    s=re.sub(r'/uni([0-9a-fA-F]{8})',decode,r.pages[i].extract_text())
    Path(f'tmp/pdfs/decoded-{i+1:02d}.txt').write_text(s)
    named=[]
    for line in s.splitlines():
        if re.search('[a-zA-Z]',line) and not any(x in line for x in ['Running','Seconds','Cost','Number','Function','Speedup']):
            if line not in named:
                named.append(line)
    print('PAGE',i+1, '\\n'+'\\n'.join(named))
print('\\nLINK TARGETS EXAMPLES')
for i in [0,4,5]:
    seen=set()
    for ref in r.pages[i].get('/Annots',[]):
        a=ref.get_object().get('/A',{})
        if a.get('/URI'):
            uri=str(a.get('/URI'))
            if uri not in seen and (i"'!=5 or any(x in uri for x in ['"'fep','hcc','mmes','lmmaes'])):
                print(i+1,uri)
            seen.add(uri)
